import { createClient } from '@supabase/supabase-js';

const SUPABASE_URL = process.env.REACT_APP_SUPABASE_URL || process.env.SUPABASE_URL || 'https://mthheftteualuokxambr.supabase.co';
const SUPABASE_ANON_KEY = process.env.REACT_APP_SUPABASE_ANON_KEY || process.env.SUPABASE_ANON_KEY || 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im10aGhlZnR0ZXVhbHVva3hhbWJyIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzM5OTM5MzcsImV4cCI6MjA4OTU2OTkzN30.GnyIsmMXdc_5832WscxEpjXClncireLNcKC-_2aj95E';

if (!SUPABASE_URL || !SUPABASE_ANON_KEY) {
  // It's fine for dev — env vars can be provided at runtime. Keep a runtime-warning.
  // Avoid throwing so builds/typechecks in CI don't fail when secrets aren't present.
  // eslint-disable-next-line no-console
  console.warn('Supabase env vars REACT_APP_SUPABASE_URL / REACT_APP_SUPABASE_ANON_KEY not set.');
}

export const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

export default supabase;
